-- Produit par node outils/formation-scripts.mjs : NE PAS EXÉCUTER sans l'accord de Teo.
-- Importe le catalogue des vidéos de la formation dans /omega → Formation.
begin;
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1000, '{"Identifiant":"decouvrir-omega","Module":"Guide de démarrage","Vidéo":"Découvrir Omega","Statut":"À tourner","Ce qu''on y apprend":"Savoir ce qu''Omega fait pour l''entreprise et où se trouve chaque chose dans l''espace.","Script":"Départ : https://omegaai.fr/espace2\n\n1. À l''écran : Vue d''ensemble de l''espace, sans bouger.\nÀ dire : Voici votre espace Omega. Omega relance vos impayés, répond aux demandes de vos clients et classe vos factures. Il prépare ce travail, et c''est vous qui validez.\n\n2. À l''écran : Survoler le panneau de gauche, de haut en bas.\nÀ dire : À gauche se trouvent vos écrans : le point du matin, ce qui attend votre accord, l''activité, puis vos systèmes, FILED pour les factures, CASHD pour les impayés, REPUT pour les demandes et OFFLOAD pour les comptes à risque.\n\n3. À l''écran : Cliquer sur « À valider ».\nÀ dire : Tout ce qui engage l''entreprise passe par ici, que ce soit un virement, une relance ou une réponse à un client. Rien ne part sans votre oui.\n\n4. À l''écran : Cliquer sur « Formation » dans le panneau.\nÀ dire : Pour chaque geste, une vidéo courte comme celle-ci vous le montre. Commencez par « Comment marche Omega ».","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'decouvrir-omega');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1001, '{"Identifiant":"valider-une-demande","Module":"Comment marche Omega","Vidéo":"Valider une demande","Statut":"À tourner","Ce qu''on y apprend":"Approuver, refuser, modifier ou déléguer une demande, seule ou par lot.","Script":"Départ : https://omegaai.fr/espace2/validations\n\n1. À l''écran : Ouvrir « À valider » et montrer les groupes : en retard, aujourd''hui, cette semaine, plus tard.\nÀ dire : Les demandes qui attendent une décision sont classées par échéance. Ce qui est en retard est en haut.\n\n2. À l''écran : Ouvrir une demande et montrer son détail.\nÀ dire : Une demande montre ce qui est proposé, le montant, et d''où elle vient.\n\n3. À l''écran : Montrer les quatre boutons, puis cliquer sur « Approuver ».\nÀ dire : Quatre décisions sont possibles : approuver, refuser, modifier la demande ou déléguer votre décision. J''approuve celle-ci.\n\n4. À l''écran : Ouvrir une autre demande, cliquer sur « Refuser » et choisir un motif.\nÀ dire : Un refus se motive toujours, et le motif reste dans le journal.\n\n5. À l''écran : Cocher plusieurs demandes, puis les décider d''un coup.\nÀ dire : Quand plusieurs demandes se ressemblent, vous pouvez les décider ensemble.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'valider-une-demande');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1002, '{"Identifiant":"mode-essai","Module":"Comment marche Omega","Vidéo":"Le mode essai","Statut":"À tourner","Ce qu''on y apprend":"Comprendre que rien ne part chez les clients tant que le gérant n''a pas basculé en réel.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Dans CASHD, Débiteurs et relances, pointer la mention « mode essai » en haut de l''écran.\nÀ dire : Chaque système s''installe en mode essai. Cette mention vous le rappelle.\n\n2. À l''écran : Survoler la mention pour faire apparaître l''explication.\nÀ dire : En essai, un message que vous validez part vers une adresse d''essai d''Omega, jamais chez votre client. Vous voyez donc exactement ce qui partirait, sans aucun risque.\n\n3. À l''écran : Rester sur l''écran.\nÀ dire : Quand les propositions vous conviennent, le gérant bascule en réel. Tant qu''il ne l''a pas fait, rien ne part.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'mode-essai');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1003, '{"Identifiant":"roles-equipe","Module":"Comment marche Omega","Vidéo":"Les rôles de l''équipe","Statut":"À tourner","Ce qu''on y apprend":"Savoir qui voit quoi et qui décide quoi.","Script":"Départ : https://omegaai.fr/espace2/equipe\n\n1. À l''écran : Ouvrir Équipe et parcourir la liste des personnes.\nÀ dire : Chaque personne de votre équipe a un rôle : gérant, administrateur, valideur, collaborateur ou lecteur.\n\n2. À l''écran : Pointer la colonne Rôle sur deux personnes aux rôles différents.\nÀ dire : Le rôle fixe ce que la personne voit et ce qu''elle peut décider. Un lecteur consulte. Un valideur approuve jusqu''à un certain montant. Le gérant décide de tout, et c''est lui qui bascule en réel.\n\n3. À l''écran : Rester sur la liste.\nÀ dire : Pour ajouter quelqu''un, il faut qu''il ait déjà un compte Omega. Sinon, écrivez-nous et nous ouvrons son accès.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'roles-equipe');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1004, '{"Identifiant":"premier-acces","Module":"Votre première semaine","Vidéo":"Le premier accès","Statut":"À tourner","Ce qu''on y apprend":"Passer les quatre écrans du premier accès.","Script":"1. À l''écran : Ouvrir le lien reçu par e-mail (à tourner sur un compte de démonstration, jamais sur un vrai client).\nÀ dire : Au premier passage, quatre écrans règlent votre espace.\n\n2. À l''écran : Écran 1 : logo, nom, SIREN, territoire.\nÀ dire : D''abord votre entreprise : son logo, son nom, son SIREN et son territoire.\n\n3. À l''écran : Écran 2 : choisir le métier et cocher ce qui prend le plus de temps.\nÀ dire : Ensuite votre métier, et ce qui vous prend le plus de temps : les demandes clients, les relances d''impayés, les documents ou les avis.\n\n4. À l''écran : Écran 3 : messagerie Google ou Microsoft, puis « plus tard ».\nÀ dire : Puis votre messagerie. Vous pouvez la brancher plus tard : nous finalisons la connexion avec vous à l''installation.\n\n5. À l''écran : Écran 4 : l''équipe, puis terminer.\nÀ dire : Enfin votre équipe. Cette étape peut attendre. Votre espace est prêt.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'premier-acces');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1005, '{"Identifiant":"point-du-matin","Module":"Votre première semaine","Vidéo":"Le point du matin","Statut":"À tourner","Ce qu''on y apprend":"Lire le point du matin et retrouver les éditions précédentes.","Script":"Départ : https://omegaai.fr/espace2/point\n\n1. À l''écran : Ouvrir Point du matin, sur l''édition du jour.\nÀ dire : Chaque matin, à 7 heures par défaut, Omega vous envoie un point par e-mail ou par WhatsApp. Vous le retrouvez aussi ici.\n\n2. À l''écran : Descendre doucement dans l''édition.\nÀ dire : Il commence par ce qu''il faut regarder en premier, puis montre ce qui a bougé depuis la dernière édition.\n\n3. À l''écran : Cliquer sur un lien du point qui mène à un écran.\nÀ dire : Chaque ligne mène à l''écran concerné.\n\n4. À l''écran : Revenir et ouvrir une édition précédente.\nÀ dire : Les sept dernières éditions restent consultables.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'point-du-matin');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1006, '{"Identifiant":"routine-a-valider","Module":"Votre première semaine","Vidéo":"Votre routine dans « À valider »","Statut":"À tourner","Ce qu''on y apprend":"Prendre l''habitude quotidienne : l''onglet « À décider par moi », du haut vers le bas.","Script":"Départ : https://omegaai.fr/espace2/validations\n\n1. À l''écran : Ouvrir À valider, onglet « À décider par moi ».\nÀ dire : Chaque jour, après le point du matin, ouvrez « À valider » sur l''onglet « À décider par moi ».\n\n2. À l''écran : Décider la première demande en haut, puis la suivante.\nÀ dire : Prenez les demandes de haut en bas : ce qui est en retard d''abord. Quelques minutes suffisent.\n\n3. À l''écran : Passer sur l''onglet « Décidées ».\nÀ dire : Ce que vous avez décidé reste ici, avec la date et le nom de la personne qui a décidé.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'routine-a-valider');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1007, '{"Identifiant":"cashd-tableau-de-bord","Module":"CASHD","Vidéo":"Le tableau de bord","Statut":"À tourner","Ce qu''on y apprend":"Lire en un coup d''œil qui vous doit quoi, et où en est chaque compte.","Script":"Départ : https://omegaai.fr/espace2/cashd\n\n1. À l''écran : Ouvrir CASHD, tableau de bord.\nÀ dire : CASHD suit qui vous doit de l''argent, depuis quand, et où en est chaque relance.\n\n2. À l''écran : Pointer les quatre états : en retard, en litige, en pause, à jour.\nÀ dire : Vos débiteurs sont rangés en quatre états : en retard, en litige, en pause et à jour.\n\n3. À l''écran : Cliquer sur un débiteur en retard.\nÀ dire : Un clic ouvre le compte : ses factures, ses relances et ce qui s''est passé.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-tableau-de-bord');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1008, '{"Identifiant":"cashd-valider-relance","Module":"CASHD","Vidéo":"Valider une relance","Statut":"À tourner","Ce qu''on y apprend":"Relire et valider les relances que CASHD a rédigées pour le jour.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Dans Débiteurs et relances, ouvrir le menu « … » et montrer « Écrire les relances du jour ».\nÀ dire : Chaque matin, CASHD rédige les relances du jour à partir de votre calendrier.\n\n2. À l''écran : Ouvrir une relance « À valider » et lire le texte.\nÀ dire : Chaque relance attend votre accord. Relisez le texte : c''est celui qui partira.\n\n3. À l''écran : Ouvrir la file de validation et approuver la relance.\nÀ dire : Vous l''approuvez dans « À valider », comme toute autre demande. Elle passe alors à « Validée, à envoyer ».\n\n4. À l''écran : Revenir sur la relance et montrer son nouvel état.\nÀ dire : Un compte ne reçoit jamais deux fois le même message.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-valider-relance');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1009, '{"Identifiant":"cashd-textes-relance","Module":"CASHD","Vidéo":"Retoucher vos textes de relance","Statut":"À tourner","Ce qu''on y apprend":"Adapter le ton de chaque palier de relance à votre façon d''écrire.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Menu « … », « Vos textes de relance ».\nÀ dire : Les relances partent de vos textes. Il y en a un par palier : le rappel courtois, la relance ferme, la mise en demeure.\n\n2. À l''écran : Ouvrir le texte du rappel courtois et en modifier une phrase.\nÀ dire : Modifiez-les pour qu''ils vous ressemblent.\n\n3. À l''écran : Rester sur le texte modifié.\nÀ dire : Les prochaines relances partiront de ce texte. Celles qui sont déjà rédigées ne changent pas.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-textes-relance');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1010, '{"Identifiant":"cashd-noter-reglement","Module":"CASHD","Vidéo":"Noter un règlement","Statut":"À tourner","Ce qu''on y apprend":"Enregistrer un paiement reçu, ce qui arrête les relances de la facture.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Ouvrir un débiteur, puis le menu d''une de ses factures.\nÀ dire : Un client vous a payé ? Ouvrez son compte, puis la facture concernée.\n\n2. À l''écran : « Noter un règlement » : saisir le montant, choisir le mode (virement, chèque…), une référence.\nÀ dire : Cliquez sur « Noter un règlement », puis saisissez le montant, le mode de paiement et une référence si vous en avez une.\n\n3. À l''écran : Valider, puis montrer le règlement dans l''activité du compte.\nÀ dire : Le règlement est enregistré, et les relances de cette facture s''arrêtent.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-noter-reglement');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1011, '{"Identifiant":"cashd-echeancier","Module":"CASHD","Vidéo":"Poser un échéancier","Statut":"À tourner","Ce qu''on y apprend":"Accorder un paiement en plusieurs fois sans que les relances continuent.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Ouvrir un débiteur, menu d''une facture, « Échéancier ».\nÀ dire : Un client demande à payer en plusieurs fois ? Ouvrez la facture, puis « Échéancier ».\n\n2. À l''écran : Montrer les trois échéances proposées, en modifier une date, saisir un motif.\nÀ dire : CASHD propose trois échéances. Ajustez les dates et les montants, et notez pourquoi vous l''accordez.\n\n3. À l''écran : Valider et montrer l''échéancier sur la facture.\nÀ dire : L''échéancier remplace l''échéance d''origine : tant que le client paie à la date, il n''est plus relancé. Seule une échéance manquée relance le cycle.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-echeancier');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1012, '{"Identifiant":"cashd-litige","Module":"CASHD","Vidéo":"Mettre une facture en litige","Statut":"À tourner","Ce qu''on y apprend":"Suspendre les relances d''une facture contestée, puis clore le litige.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Menu d''une facture, « Mettre en litige », saisir le motif.\nÀ dire : Quand un client conteste une facture, mettez-la en litige. Les relances de cette facture s''arrêtent.\n\n2. À l''écran : Montrer « Contestation partielle » dans le même menu, sans valider.\nÀ dire : S''il ne conteste qu''une partie, la contestation partielle sort cette part du cycle et continue de relancer le reste.\n\n3. À l''écran : Ouvrir Litiges et pauses, puis « Clore le litige » sur la facture.\nÀ dire : Les litiges en cours se retrouvent ici. Une fois le désaccord réglé, closez le litige : la facture reprend son cours.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-litige');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1013, '{"Identifiant":"cashd-pause","Module":"CASHD","Vidéo":"Mettre un compte en pause","Statut":"À tourner","Ce qu''on y apprend":"Arrêter toutes les relances d''un client le temps d''une discussion, puis les reprendre.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Ouvrir un débiteur, menu du compte, « Mettre en pause ».\nÀ dire : Vous êtes en discussion avec un client ? Mettez son compte en pause : toute relance en attente est coupée, même celle qui est déjà écrite.\n\n2. À l''écran : Montrer le compte passé à l''état « En pause ».\nÀ dire : Le compte passe à l''état « En pause », et la pause est datée dans le journal.\n\n3. À l''écran : Même menu, « Reprendre les relances », saisir la raison.\nÀ dire : Quand c''est réglé, reprenez les relances en disant pourquoi : elles repartent au palier où elles en étaient.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-pause');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1014, '{"Identifiant":"cashd-reponse-recue","Module":"CASHD","Vidéo":"Traiter une réponse reçue","Statut":"À tourner","Ce qu''on y apprend":"Trancher quand un client répond à une relance.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Filtrer les relances à l''état « Réponse à trancher », en ouvrir une.\nÀ dire : Quand un client répond à une relance, CASHD vous la montre ici, à l''état « Réponse à trancher ».\n\n2. À l''écran : Lire la réponse dans l''activité de la relance.\nÀ dire : CASHD a lu la réponse et propose une lecture : une contestation, un règlement annoncé, ou un contact qui a quitté l''entreprise.\n\n3. À l''écran : Cliquer sur « Accepter » (ou « Écarter » sur une autre).\nÀ dire : Si la lecture est juste, acceptez : une contestation met la facture en litige, un règlement annoncé met le compte en pause le temps du paiement. Sinon, écartez : rien ne change.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-reponse-recue');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1015, '{"Identifiant":"cashd-devis","Module":"CASHD","Vidéo":"Les devis sans réponse","Statut":"À tourner","Ce qu''on y apprend":"Suivre les devis en attente et noter un accord donné de vive voix.","Script":"Départ : https://omegaai.fr/espace2/cashd/devis\n\n1. À l''écran : Ouvrir Devis sans réponse.\nÀ dire : CASHD suit aussi vos devis. Sans réponse, un devis est relancé après trois jours, puis après sept.\n\n2. À l''écran : Sur un devis en attente, « Accord de vive voix ».\nÀ dire : Si le client vous a dit oui au téléphone, notez l''accord : les relances du devis s''arrêtent.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-devis');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1016, '{"Identifiant":"cashd-balance","Module":"CASHD","Vidéo":"La balance âgée","Statut":"À tourner","Ce qu''on y apprend":"Lire ce qui est dû par ancienneté et l''envoyer à votre comptable.","Script":"Départ : https://omegaai.fr/espace2/cashd/balance\n\n1. À l''écran : Ouvrir Balance âgée.\nÀ dire : La balance âgée montre ce qui vous est dû, rangé par ancienneté.\n\n2. À l''écran : Pointer la colonne des retards les plus anciens.\nÀ dire : Les montants les plus anciens sont les plus difficiles à récupérer : regardez-les en premier.\n\n3. À l''écran : Cliquer sur « Exporter la balance ».\nÀ dire : Exportez-la vers un tableur pour votre comptable ou votre banque.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-balance');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1017, '{"Identifiant":"cashd-deposer-export","Module":"CASHD","Vidéo":"Déposer un export du facturier","Statut":"À tourner","Ce qu''on y apprend":"Mettre CASHD à jour avec les factures de votre logiciel de facturation.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Menu « … », « Déposer un export du facturier ».\nÀ dire : CASHD part de vos factures. Si votre logiciel de facturation n''est pas branché, déposez-en un export.\n\n2. À l''écran : Glisser un fichier d''exemple dans la fenêtre (sans valider en base réelle).\nÀ dire : Glissez le fichier dans cette fenêtre : CASHD lit les factures et les paiements et met chaque compte à jour.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-deposer-export');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1018, '{"Identifiant":"cashd-qui-valide","Module":"CASHD","Vidéo":"Qui valide quoi","Statut":"À tourner","Ce qu''on y apprend":"Connaître les seuils de validation par montant et les plafonds d''encours.","Script":"Départ : https://omegaai.fr/espace2/cashd/suivi\n\n1. À l''écran : Ouvrir une relance d''un petit montant, puis une d''un gros montant.\nÀ dire : Qui valide une relance dépend du montant. Par défaut, tout valideur peut le faire jusqu''à 2 000 euros, un administrateur ou le gérant au-delà, et le gérant seul à partir de 10 000 euros.\n\n2. À l''écran : Ouvrir Risque client et pointer un plafond d''encours.\nÀ dire : Vous pouvez aussi fixer un plafond d''encours par client. CASHD vous prévient quand il est dépassé, et le plafond est daté dans le journal.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'cashd-qui-valide');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1019, '{"Identifiant":"filed-facture-arrive","Module":"FILED","Vidéo":"Une facture qui arrive","Statut":"À tourner","Ce qu''on y apprend":"Suivre une facture depuis son arrivée jusqu''à son dossier, et lire ce que FILED en a compris.","Script":"Départ : https://omegaai.fr/espace2/filed\n\n1. À l''écran : Ouvrir FILED, Documents reçus, et montrer la liste.\nÀ dire : Chaque facture qui arrive, par e-mail ou déposée à la main, apparaît ici. FILED la lit, recoupe ses montants et la range.\n\n2. À l''écran : Ouvrir une facture de la liste.\nÀ dire : Ouvrez une pièce : vous voyez son fournisseur, ses montants, son échéance, et où elle en est.\n\n3. À l''écran : Cliquer sur une valeur lue (le total TTC, par exemple).\nÀ dire : Cliquez sur une valeur : elle se surligne dans la pièce. Vous voyez exactement où FILED l''a lue.\n\n4. À l''écran : Montrer l''activité de la pièce, en bas.\nÀ dire : L''activité retrace tout ce qui est arrivé à la pièce depuis sa réception.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'filed-facture-arrive');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1020, '{"Identifiant":"filed-deposer","Module":"FILED","Vidéo":"Déposer un document","Statut":"À tourner","Ce qu''on y apprend":"Ajouter à la main une facture reçue sur papier ou hors de la messagerie.","Script":"Départ : https://omegaai.fr/espace2/filed\n\n1. À l''écran : Bouton « Déposer un document ».\nÀ dire : Une facture vous arrive sur papier, ou par un autre canal ? Déposez-la ici.\n\n2. À l''écran : Montrer la fenêtre de dépôt, sans valider.\nÀ dire : Le fichier reçoit un numéro, il est lu, puis contrôlé comme tout document reçu par e-mail.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'filed-deposer');
