select 'formation', 1021, '{"Identifiant":"filed-boite","Module":"FILED","Vidéo":"La boîte de réception","Statut":"À tourner","Ce qu''on y apprend":"Trier les e-mails reçus par FILED.","Script":"Départ : https://omegaai.fr/espace2/filed/boite\n\n1. À l''écran : Ouvrir Boîte de réception, onglets Nouveaux, Lus, Traités.\nÀ dire : La boîte de réception montre les e-mails que FILED a reçus. Les pièces jointes en sont tirées automatiquement.\n\n2. À l''écran : Ouvrir un e-mail, puis « Marquer comme lu ».\nÀ dire : Un e-mail que vous avez vu se marque comme lu.\n\n3. À l''écran : Sur un autre e-mail sans intérêt, « Écarter ».\nÀ dire : Une publicité ou un e-mail sans pièce s''écarte, pour garder la boîte propre.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'filed-boite');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1022, '{"Identifiant":"filed-dossier-facture","Module":"FILED","Vidéo":"Le dossier d''une facture","Statut":"À tourner","Ce qu''on y apprend":"Trouver dans le dossier tout ce qu''on peut faire sur une facture.","Script":"Départ : https://omegaai.fr/espace2/filed\n\n1. À l''écran : Ouvrir une facture, puis son menu de gestes.\nÀ dire : Tous les gestes sur une facture partent de son dossier : corriger une valeur, ouvrir un litige, rattacher une commande, transmettre à la comptabilité.\n\n2. À l''écran : Cliquer sur « Voir la pièce ».\nÀ dire : La pièce d''origine reste toujours consultable, telle qu''elle est arrivée.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'filed-dossier-facture');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1023, '{"Identifiant":"filed-corriger","Module":"FILED","Vidéo":"Corriger une valeur","Statut":"À tourner","Ce qu''on y apprend":"Rectifier un montant, une date ou un numéro mal lu.","Script":"Départ : https://omegaai.fr/espace2/filed\n\n1. À l''écran : Dans le dossier, « Corriger une valeur… », choisir le montant, saisir la bonne valeur.\nÀ dire : Si FILED a mal lu une valeur, corrigez-la. Indiquez la bonne valeur et pourquoi.\n\n2. À l''écran : Montrer la nouvelle version de la facture et les contrôles rejoués.\nÀ dire : La correction crée une nouvelle version de la facture, et tous les contrôles sont rejoués. L''ancienne version reste dans l''historique.\n\n3. À l''écran : Sur une autre facture, « Confirmer la valeur non vérifiée… ».\nÀ dire : Quand FILED n''est pas sûr d''une valeur, il vous demande de la confirmer.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'filed-corriger');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1024, '{"Identifiant":"filed-controles","Module":"FILED","Vidéo":"Contrôles et fraude","Statut":"À tourner","Ce qu''on y apprend":"Comprendre ce qui bloque une facture et lever un contrôle à bon escient.","Script":"Départ : https://omegaai.fr/espace2/filed/controles\n\n1. À l''écran : Ouvrir Contrôles et fraude, sur « Bloquants » puis « À vérifier ».\nÀ dire : FILED contrôle chaque facture : le compte entre HT, TVA et TTC, l''IBAN, les doublons. Ce qui bloque est ici, et ce qui demande un œil aussi.\n\n2. À l''écran : Ouvrir un contrôle, puis « Lever avec un motif… ».\nÀ dire : Si vous avez vérifié et que tout est en ordre, levez le contrôle en donnant le motif. Il reste au journal.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'filed-controles');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1025, '{"Identifiant":"filed-fournisseur","Module":"FILED","Vidéo":"Confirmer un fournisseur et son IBAN","Statut":"À tourner","Ce qu''on y apprend":"Confirmer un nouveau fournisseur et faire valider son IBAN avant tout paiement.","Script":"Départ : https://omegaai.fr/espace2/filed/fournisseurs\n\n1. À l''écran : Ouvrir Fournisseurs, onglet « À confirmer ».\nÀ dire : Un fournisseur naît de sa première facture. Avant de le payer, il faut le confirmer.\n\n2. À l''écran : « Confirmer ce fournisseur… », saisir ce qui a été vérifié.\nÀ dire : Dites ce que vous avez vérifié : un bon de commande, un appel au numéro connu, un contrat. Celui qui a déposé la pièce ne peut pas confirmer lui-même : une autre personne le fait.\n\n3. À l''écran : « Proposer un IBAN… », saisir d''où il vient.\nÀ dire : Un IBAN proposé part en validation dans « À valider ». Une personne habilitée doit l''approuver avant tout paiement.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'filed-fournisseur');
insert into omega_lignes (tableau, ordre, donnees)
