select 'formation', 1033, '{"Identifiant":"reput-repondre","Module":"REPUT","Vidéo":"Répondre à une demande","Statut":"À tourner","Ce qu''on y apprend":"Valider, corriger ou refuser une réponse préparée.","Script":"Départ : https://omegaai.fr/espace2/reput\n\n1. À l''écran : Sur une demande, « Valider et envoyer ».\nÀ dire : Si la réponse vous convient, validez-la et elle part.\n\n2. À l''écran : Sur une autre, « Corriger la réponse », modifier une phrase, valider.\nÀ dire : Si elle ne vous ressemble pas, corrigez-la avant de l''envoyer.\n\n3. À l''écran : Sur une troisième, « Refuser la réponse… », saisir le motif.\nÀ dire : Si elle est fausse, refusez-la en disant pourquoi : la demande vous revient.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'reput-repondre');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1034, '{"Identifiant":"reput-base","Module":"REPUT","Vidéo":"La base de connaissances","Statut":"À tourner","Ce qu''on y apprend":"Créer, corriger et mettre en vigueur une fiche.","Script":"Départ : https://omegaai.fr/espace2/reput/base\n\n1. À l''écran : Ouvrir Base de connaissances, survoler les états : en vigueur, brouillon, à revoir.\nÀ dire : REPUT ne répond qu''avec ce qui est dans votre base. Chaque fiche est en vigueur, en brouillon ou à revoir.\n\n2. À l''écran : « Nouvelle fiche », saisir une question et sa réponse.\nÀ dire : Ajoutez une fiche pour chaque question qui revient : vos horaires, vos délais, vos tarifs.\n\n3. À l''écran : « Valider et mettre en vigueur ».\nÀ dire : Une fois en vigueur, la prochaine réponse la cite. Un brouillon attend qu''un valideur le mette en vigueur.\n\n4. À l''écran : Sur une fiche périmée, « Retirer la fiche… ».\nÀ dire : Une fiche retirée ne sert plus.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'reput-base');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1035, '{"Identifiant":"reput-partir-seul","Module":"REPUT","Vidéo":"Laisser partir seul","Statut":"À tourner","Ce qu''on y apprend":"Autoriser, sujet par sujet, l''envoi sans relecture, et savoir le couper.","Script":"Départ : https://omegaai.fr/espace2/reput/sujets\n\n1. À l''écran : Ouvrir Sujets autorisés.\nÀ dire : Au début, chaque réponse attend votre validation. Quand un sujet vous convient, vous pouvez le laisser partir seul.\n\n2. À l''écran : Sur un sujet simple (les horaires), « Autoriser l''envoi seul ».\nÀ dire : Les réponses tirées de votre base sur ce sujet partent alors sans relecture.\n\n3. À l''écran : Montrer « Couper l''envoi automatique… » et le motif demandé.\nÀ dire : À tout moment, coupez l''envoi automatique en donnant le motif : toutes les réponses attendent de nouveau votre validation.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'reput-partir-seul');
