select 'formation', 1036, '{"Identifiant":"reput-urgences","Module":"REPUT","Vidéo":"Urgences et réclamations","Statut":"À tourner","Ce qu''on y apprend":"Savoir comment REPUT traite une urgence, une réclamation, ou un client qui demande une personne.","Script":"Départ : https://omegaai.fr/espace2/reput/urgences\n\n1. À l''écran : Ouvrir Urgences et escalade.\nÀ dire : Certaines demandes ne reçoivent jamais de réponse automatique : les urgences, les réclamations, les clients en litige, et ceux qui demandent à parler à quelqu''un.\n\n2. À l''écran : Pointer le délai d''une urgence (une heure) et d''une réclamation (quatre heures).\nÀ dire : Chaque sujet porte le délai que vous avez fixé. Passé ce délai, la demande remonte au responsable.\n\n3. À l''écran : Montrer la règle hors horaires.\nÀ dire : Par défaut, personne n''est appelé la nuit : le client reçoit tout de suite une réponse honnête avec vos horaires, et son urgence passe en tête à l''ouverture.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'reput-urgences');
