select 'formation', 1044, '{"Identifiant":"daliro-chantier","Module":"DALIRO","Vidéo":"Créer et ouvrir un chantier","Statut":"À tourner","Ce qu''on y apprend":"Créer un chantier, puis l''ouvrir une fois son maître d''ouvrage désigné.","Script":"Départ : https://omegaai.fr/espace2/daliro\n\n1. À l''écran : Cliquer sur « Nouveau chantier », remplir, puis « Créer le chantier ».\nÀ dire : Un chantier naît en préparation. Le département, le territoire et le régime de TVA se déduisent du code postal.\n\n2. À l''écran : Montrer le message : posez ses lots, son marché, puis ouvrez-le.\nÀ dire : Posez ses lots et son marché.\n\n3. À l''écran : Dans la fiche, menu « Actions sur le chantier », « Ouvrir le chantier… », « Confirmer ».\nÀ dire : Puis ouvrez-le. Il faut un maître d''ouvrage désigné dans l''annuaire : c''est lui qui signe les avenants.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-chantier');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1045, '{"Identifiant":"daliro-ranger","Module":"DALIRO","Vidéo":"Ranger un message du terrain","Statut":"À tourner","Ce qu''on y apprend":"Rattacher à son chantier une photo, un vocal ou un message reçu du terrain.","Script":"Départ : https://omegaai.fr/espace2/daliro/a-ranger\n\n1. À l''écran : Ouvrir À ranger, puis un message.\nÀ dire : Les photos, vocaux et messages envoyés depuis le terrain sans chantier arrivent ici.\n\n2. À l''écran : Pastille « Chantier », choisir le chantier.\nÀ dire : Choisissez son chantier : le message y est rangé.\n\n3. À l''écran : Sur un autre message, « Écarter le message… », motif facultatif, « Écarter le message ».\nÀ dire : Un message sans intérêt s''écarte. Il quitte la file sans être rangé, et reste au journal.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-ranger');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1046, '{"Identifiant":"daliro-avenant","Module":"DALIRO","Vidéo":"Ouvrir et chiffrer un avenant","Statut":"À tourner","Ce qu''on y apprend":"Transformer une demande du terrain en avenant chiffré sur vos prix.","Script":"Départ : https://omegaai.fr/espace2/daliro/a-ranger\n\n1. À l''écran : Sur un message, « Ajouter un avenant », choisir le chantier, remplir « Ce qui est demandé en plus », puis « Ranger à … et ouvrir ».\nÀ dire : Un client demande des travaux en plus ? Le message devient l''origine d''un avenant en brouillon.\n\n2. À l''écran : « Voir l''avenant », puis « Chiffrer une ligne », « Chiffrer ».\nÀ dire : Chiffrez chaque ligne sur un prix validé de votre bibliothèque. Un prix saisi librement est proposé à la bibliothèque, à valider.\n\n3. À l''écran : « Soumettre à la signature », « Soumettre ».\nÀ dire : Soumettez l''avenant : une demande de validation part dans « À valider ». Celui qui a chiffré ne décide pas.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-avenant');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1047, '{"Identifiant":"daliro-signer","Module":"DALIRO","Vidéo":"Signer un avenant","Statut":"À tourner","Ce qu''on y apprend":"Faire signer un avenant validé, au bureau ou sur place.","Script":"Départ : https://omegaai.fr/espace2/daliro/a-faire\n\n1. À l''écran : Dans À faire, geste « Signer », qui ouvre la fiche, onglet Argent.\nÀ dire : Une fois l''avenant approuvé, il se signe.\n\n2. À l''écran : « Signer », puis « Signer ».\nÀ dire : Signé, ses travaux entrent dans l''engagé du lot.\n\n3. À l''écran : Montrer « Faire signer sur place », « Préparer le lien ».\nÀ dire : Sur le chantier, préparez un lien à usage unique : le client signe du doigt sur le téléphone du chef d''équipe.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-signer');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1048, '{"Identifiant":"daliro-passages","Module":"DALIRO","Vidéo":"Confirmer les passages à J-2","Statut":"À tourner","Ce qu''on y apprend":"Noter la réponse d''un sous-traitant et gérer un passage décliné.","Script":"Départ : https://omegaai.fr/espace2/daliro/equipes\n\n1. À l''écran : Ouvrir Équipes, onglet « Non confirmés ».\nÀ dire : Deux jours avant chaque passage, la venue du sous-traitant se confirme.\n\n2. À l''écran : Menu du passage, « Noter la réponse », « Confirmé », « Noter : confirmé ».\nÀ dire : Une réponse reçue par téléphone se note ici, comme celle reçue par WhatsApp.\n\n3. À l''écran : Sur un autre, « Noter le passage décliné ».\nÀ dire : Un passage décliné propose des remplaçants et prévient le conducteur de travaux.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-passages');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1049, '{"Identifiant":"daliro-planning","Module":"DALIRO","Vidéo":"Noter un passage fait, recaler la suite","Statut":"À tourner","Ce qu''on y apprend":"Tenir le planning à jour.","Script":"Départ : https://omegaai.fr/espace2/daliro/a-faire\n\n1. À l''écran : Dans la fiche, onglet Terrain, Planning, « Noter fait ».\nÀ dire : Un passage terminé se note fait.\n\n2. À l''écran : « Recaler », saisir la nouvelle fin, « Voir ce qui bouge », « Recaler ».\nÀ dire : Un retard ? Donnez la nouvelle fin : la suite glisse en jours ouvrés, chaque passage garde sa durée.\n\n3. À l''écran : Dans À faire, cocher plusieurs passages, « Noter faits ».\nÀ dire : Plusieurs passages se notent faits d''un coup depuis À faire.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-planning');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1050, '{"Identifiant":"daliro-absence","Module":"DALIRO","Vidéo":"Noter une absence","Statut":"À tourner","Ce qu''on y apprend":"Empêcher qu''un sous-traitant absent soit proposé.","Script":"Départ : https://omegaai.fr/espace2/daliro/equipes\n\n1. À l''écran : Équipes, « Noter une absence », choisir la période, « Noter l''absence ».\nÀ dire : Les jours notés ne sont plus proposés pour ce sous-traitant, ni pour un passage, ni comme remplaçant.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-absence');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1051, '{"Identifiant":"daliro-prix","Module":"DALIRO","Vidéo":"La bibliothèque de prix","Statut":"À tourner","Ce qu''on y apprend":"Poser et valider vos prix.","Script":"Départ : https://omegaai.fr/espace2/daliro/reglages\n\n1. À l''écran : Réglages, Bibliothèque de prix, « Poser un prix », « Poser et valider ».\nÀ dire : Vos avenants se chiffrent sur cette bibliothèque. Posez vos prix ici.\n\n2. À l''écran : Sur un prix proposé, « Valider ce prix… », « Valider le prix ».\nÀ dire : Un prix saisi pendant un chiffrage arrive ici, proposé. Validez-le. Un nouveau prix validé pour la même désignation retire l''ancien.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'daliro-prix');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1052, '{"Identifiant":"lorani-projet","Module":"LORANI","Vidéo":"Créer un projet et son permis","Statut":"À tourner","Ce qu''on y apprend":"Ouvrir un projet, puis saisir son permis.","Script":"Départ : https://omegaai.fr/espace2/lorani\n\n1. À l''écran : « Nouveau projet », remplir le lieu, « Ouvrir le projet ».\nÀ dire : Le lieu du terrain fixe les règles : le code postal dit quel droit de l''urbanisme s''applique.\n\n2. À l''écran : Dans le projet, « Nouveau permis », choisir le type, « Saisir le permis ».\nÀ dire : Le type fixe le délai de droit commun : un mois pour une déclaration préalable, deux pour une maison, trois pour les autres permis.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-projet');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1053, '{"Identifiant":"lorani-courrier","Module":"LORANI","Vidéo":"Déposer un courrier de la mairie","Statut":"À tourner","Ce qu''on y apprend":"Faire lire un courrier de la mairie pour mettre le calendrier à jour.","Script":"Départ : https://omegaai.fr/espace2/lorani\n\n1. À l''écran : Dans le projet, « Déposer un courrier de la mairie… », choisir le fichier, laisser « Laisser Lorani reconnaître », « Déposer ».\nÀ dire : Récépissé, lettre de délai, demande de pièces, arrêté : déposez le courrier, LORANI le lit.\n\n2. À l''écran : Montrer la date proposée.\nÀ dire : Il vous propose la date qu''il y a lue. Rien n''est appliqué tant que vous ne l''avez pas confirmée.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-courrier');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1054, '{"Identifiant":"lorani-confirmer","Module":"LORANI","Vidéo":"Confirmer une date lue","Statut":"À tourner","Ce qu''on y apprend":"Valider ou écarter ce que LORANI a lu sur un courrier.","Script":"Départ : https://omegaai.fr/espace2/lorani/courrier\n\n1. À l''écran : Courrier à ranger, onglet « À confirmer », « Confirmer », corriger si besoin, « Confirmer ».\nÀ dire : Vérifiez la date contre le courrier et corrigez-la s''il dit autre chose : c''est la valeur confirmée qui compte, et le calendrier est recalculé.\n\n2. À l''écran : Sur une autre, « Écarter ».\nÀ dire : Une lecture fausse s''écarte : le permis n''en garde rien, et le motif est inscrit au journal.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-confirmer');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1055, '{"Identifiant":"lorani-tacite","Module":"LORANI","Vidéo":"Confirmer une décision tacite","Statut":"À tourner","Ce qu''on y apprend":"Prendre acte d''un permis obtenu sans réponse de la mairie.","Script":"Départ : https://omegaai.fr/espace2/lorani/courrier\n\n1. À l''écran : Sur une décision implicite, « Confirmer ».\nÀ dire : Quand la mairie n''a pas répondu dans le délai, la décision est tacite. Le système la date lui-même : elle ne se saisit pas à la main.\n\n2. À l''écran : Montrer le message après confirmation.\nÀ dire : Affichez ensuite le permis sur le terrain, puis saisissez le premier jour d''affichage.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-tacite');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1056, '{"Identifiant":"lorani-evenement","Module":"LORANI","Vidéo":"Saisir ce qui arrive sur un permis","Statut":"À tourner","Ce qu''on y apprend":"Noter un dépôt, un arrêté, l''affichage ou un recours.","Script":"Départ : https://omegaai.fr/espace2/lorani\n\n1. À l''écran : Page du permis, « Copier ou saisir ce qui est arrivé », « Permis affiché sur le terrain… », « Saisir ».\nÀ dire : Chaque événement du permis se saisit ici. Le premier jour d''affichage ouvre le délai de recours des tiers, deux mois.\n\n2. À l''écran : Montrer « Recours reçu… ».\nÀ dire : Un recours reçu se saisit aussi : tant que son issue n''est pas saisie, le permis n''est pas purgé.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-evenement');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1057, '{"Identifiant":"lorani-questions","Module":"LORANI","Vidéo":"Suivre une question","Statut":"À tourner","Ce qu''on y apprend":"Poser une question à une entreprise et la suivre jusqu''à la réponse.","Script":"Départ : https://omegaai.fr/espace2/lorani/questions\n\n1. À l''écran : « Nouvelle question », « Poser ».\nÀ dire : Notez la question posée à une entreprise ou un bureau d''études. Rien ne lui est envoyé : la question est suivie ici.\n\n2. À l''écran : « Réponse reçue », « Noter la réponse ».\nÀ dire : Sans réponse au bout de huit jours, elle remonte au point du matin.\n\n3. À l''écran : « Solder ».\nÀ dire : Une fois traitée, soldez-la : elle sort des points en suspens.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-questions');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1058, '{"Identifiant":"lorani-viser","Module":"LORANI","Vidéo":"Viser une situation, lever une réserve","Statut":"À tourner","Ce qu''on y apprend":"Viser les situations et lever les réserves.","Script":"Départ : https://omegaai.fr/espace2/lorani/a-viser\n\n1. À l''écran : À viser, cliquer une situation, « Viser » (ou « Rectifier »).\nÀ dire : Visée, la situation vaut pour le cumul admis ; rectifiée, elle retient le montant que vous indiquez.\n\n2. À l''écran : Sur un document, avis VSO, VAO ou Refusé, « Rendre l''avis ».\nÀ dire : L''avis rendu clôt l''échéance au registre des délais.\n\n3. À l''écran : Sur une réserve, « Lever ».\nÀ dire : Une réserve levée est datée d''aujourd''hui.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-viser');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1059, '{"Identifiant":"lorani-export","Module":"LORANI","Vidéo":"Exporter le dossier daté","Statut":"À tourner","Ce qu''on y apprend":"Garder la trace datée d''un projet.","Script":"Départ : https://omegaai.fr/espace2/lorani\n\n1. À l''écran : Dans le projet, « Options du projet », « Exporter le dossier daté ».\nÀ dire : Le dossier daté sort en registre PDF et Excel, dans une archive.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'lorani-export');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1060, '{"Identifiant":"tavaro-retours","Module":"TAVARO","Vidéo":"Voir ce qui attend","Statut":"À tourner","Ce qu''on y apprend":"Trouver les retours à chiffrer et les factures en attente.","Script":"Départ : https://omegaai.fr/espace2/tavaro/retours\n\n1. À l''écran : Retours à facturer, menu « Filtrer par famille », « Retours à chiffrer ».\nÀ dire : Les retours se rangent par famille : à chiffrer, à valider, bloqués.\n\n2. À l''écran : « Filtrer par agence », puis cliquer un contrat.\nÀ dire : Filtrez par agence, et ouvrez un contrat : son dossier s''affiche à droite.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-retours');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1061, '{"Identifiant":"tavaro-etat-lieux","Module":"TAVARO","Vidéo":"L''état des lieux signé","Statut":"À tourner","Ce qu''on y apprend":"Faire signer l''état des lieux de départ.","Script":"Départ : https://omegaai.fr/espace2/tavaro/retours\n\n1. À l''écran : Dans la fiche du contrat, « Faire l''état de départ », « Enregistrer et faire signer ».\nÀ dire : Sans état de départ signé, un dommage facturé au retour se conteste facilement.\n\n2. À l''écran : Saisir le nom du signataire, « Signer l''état des lieux ».\nÀ dire : Le locataire relit et signe. Une empreinte du contenu est gardée : l''état ne changera plus.\n\n3. À l''écran : Montrer « Le client ne signe pas ».\nÀ dire : S''il refuse de signer, clôturez sans signature avec un motif : les photos font foi, et les dommages iront à la direction, hors barème.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-etat-lieux');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1062, '{"Identifiant":"tavaro-retour","Module":"TAVARO","Vidéo":"Chiffrer un retour","Statut":"À tourner","Ce qu''on y apprend":"Chiffrer les dommages d''un retour sur le barème.","Script":"Départ : https://omegaai.fr/espace2/tavaro/retours\n\n1. À l''écran : Fiche du contrat, « Chiffrer le retour », « Ajouter un dommage » avec sa preuve.\nÀ dire : Relevez les dommages au retour. TAVARO les compare à l''état des lieux de départ.\n\n2. À l''écran : « Ajouter un poste (nettoyage, clé, frais…) », puis « Chiffrer le retour ».\nÀ dire : Chaque poste est chiffré selon le barème. La facture n''est proposée qu''à l''agence.\n\n3. À l''écran : Montrer un dommage sans preuve.\nÀ dire : Sans preuve, la proposition reste « preuve manquante » et aucune facture ne part.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-retour');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1063, '{"Identifiant":"tavaro-valider","Module":"TAVARO","Vidéo":"Valider la facture","Statut":"À tourner","Ce qu''on y apprend":"Approuver ou refuser une facture proposée.","Script":"Départ : https://omegaai.fr/espace2/tavaro/retours\n\n1. À l''écran : Fiche du contrat, « Ouvrir la file « À valider » », « Consulter la demande ».\nÀ dire : La facture proposée attend l''agence dans « À valider ».\n\n2. À l''écran : « Approuver » (ou « Refuser »).\nÀ dire : Celui qui a chiffré le retour ne décide pas : une autre personne approuve. Refusée, la facture se rechiffre si quelque chose reste dû.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-valider');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1064, '{"Identifiant":"tavaro-facture","Module":"TAVARO","Vidéo":"Suivre une facture","Statut":"À tourner","Ce qu''on y apprend":"Noter un règlement, relancer, demander un avoir ou passer en litige.","Script":"Départ : https://omegaai.fr/espace2/tavaro/retours\n\n1. À l''écran : Bloc Factures, déplier une facture, « Réglée », « Confirmer le règlement ».\nÀ dire : Le règlement est daté et la facture ne bouge plus.\n\n2. À l''écran : « Relancer », « Envoyer la relance ».\nÀ dire : Une relance attend un accord dans « À valider » avant de partir. Sans geste de votre part, TAVARO en prépare une sept jours après l''échéance.\n\n3. À l''écran : « Demander un avoir », saisir ce que la facture avait de faux.\nÀ dire : Une facture émise ne se modifie pas : l''avoir la corrige, la direction décide sous 48 heures.\n\n4. À l''écran : « Litige », saisir la contestation.\nÀ dire : La contestation écrite du client suspend le recouvrement.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-facture');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1065, '{"Identifiant":"tavaro-prolonger","Module":"TAVARO","Vidéo":"Prolonger un contrat","Statut":"À tourner","Ce qu''on y apprend":"Prolonger, décaler la restitution ou offrir un retard.","Script":"Départ : https://omegaai.fr/espace2/tavaro/retours\n\n1. À l''écran : Fiche du contrat, « Prolonger », choisir la nature, « Enregistrer ».\nÀ dire : Une prolongation déplace le retour prévu. Une restitution décalée le déplace sans frais. Un retard offert annule le poste retard. Le chef d''agence ou la direction amende un contrat.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-prolonger');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1066, '{"Identifiant":"tavaro-amendes","Module":"TAVARO","Vidéo":"Désigner le conducteur d''une amende","Statut":"À tourner","Ce qu''on y apprend":"Enregistrer un avis de contravention et consigner la désignation.","Script":"Départ : https://omegaai.fr/espace2/tavaro/amendes\n\n1. À l''écran : Amendes, « Enregistrer un avis », « Enregistrer ».\nÀ dire : Un avis de contravention se désigne sous 45 jours.\n\n2. À l''écran : Ouvrir l''avis, « Désigner le conducteur », « Une personne », « Consigner la désignation ».\nÀ dire : Faites la désignation sur antai.gouv.fr, puis consignez ici ce qui a été envoyé : TAVARO garde la preuve et arrête les alertes. La direction ou un valideur la fait.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-amendes');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1067, '{"Identifiant":"tavaro-bareme","Module":"TAVARO","Vidéo":"Publier un barème","Statut":"À tourner","Ce qu''on y apprend":"Mettre en vigueur un nouveau barème.","Script":"Départ : https://omegaai.fr/espace2/tavaro/reglages\n\n1. À l''écran : Réglages, onglet « Barème », « Publier un barème », remplir, « Publier ».\nÀ dire : Sans barème en vigueur à la date du départ, aucun retour ne se chiffre. Seule la direction publie le barème ; il s''applique aux départs à partir de sa date d''effet.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tavaro-bareme');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1068, '{"Identifiant":"tiroma-point","Module":"TIROMA","Vidéo":"Le point du jour","Statut":"À tourner","Ce qu''on y apprend":"Lire le cabinet en une page chaque matin.","Script":"Départ : https://omegaai.fr/espace2/tiroma\n\n1. À l''écran : Ouvrir Aujourd''hui.\nÀ dire : Chaque matin, TIROMA lit l''agenda, les plans et les devis du logiciel du cabinet, sans y écrire.\n\n2. À l''écran : Pointer les groupes : créneaux à sauver, plans sans rendez-vous, avant les rendez-vous.\nÀ dire : Il vous montre les créneaux à sauver, les plans signés sans rendez-vous et ce qu''il faut vérifier avant les rendez-vous.\n\n3. À l''écran : Cliquer une ligne.\nÀ dire : Chaque ligne mène à l''écran où se fait le geste.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tiroma-point');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1069, '{"Identifiant":"tiroma-creneau","Module":"TIROMA","Vidéo":"Sauver un créneau libéré","Statut":"À tourner","Ce qu''on y apprend":"Proposer un créneau libéré et noter l''appel.","Script":"Départ : https://omegaai.fr/espace2/tiroma/creneaux\n\n1. À l''écran : Créneaux et appels, « Créneaux à sauver », ouvrir un créneau.\nÀ dire : Un rendez-vous annulé libère un créneau. TIROMA propose les patients qui peuvent le reprendre.\n\n2. À l''écran : « Noter l''appel », « Rendez-vous pris », « Noter ».\nÀ dire : Appelez le patient, puis notez l''issue de l''appel.\n\n3. À l''écran : Pointer le rappel : le rendez-vous se pose dans le logiciel du cabinet.\nÀ dire : Le rendez-vous se pose dans le logiciel du cabinet : c''est lui qui fait foi. TIROMA le confirmera au prochain relevé.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tiroma-creneau');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1070, '{"Identifiant":"tiroma-attente","Module":"TIROMA","Vidéo":"La liste d''attente","Statut":"À tourner","Ce qu''on y apprend":"Inscrire un patient en liste d''attente et l''en retirer.","Script":"Départ : https://omegaai.fr/espace2/tiroma/creneaux\n\n1. À l''écran : « Liste d''attente », remplir le patient, le soin, la durée, cocher « Patient gêné (douleur) » s''il le faut, « Inscrire ».\nÀ dire : TIROMA proposera le patient au premier créneau libéré qui lui convient, après les plans acceptés. Un patient gêné est appelé en premier.\n\n2. À l''écran : Sur un patient, « Retirer de la liste », choisir le motif, « Retirer ».\nÀ dire : Un patient se retire avec un motif, qui reste dans le journal du cabinet.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tiroma-attente');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1071, '{"Identifiant":"tiroma-mutuelle","Module":"TIROMA","Vidéo":"Noter la mutuelle d''un plan","Statut":"À tourner","Ce qu''on y apprend":"Suivre l''accord de la mutuelle sur un plan de traitement.","Script":"Départ : https://omegaai.fr/espace2/tiroma/plans\n\n1. À l''écran : Plans et devis, cliquer une carte, « Noter la mutuelle ».\nÀ dire : Le logiciel du cabinet n''exporte pas la mutuelle : notez ici la demande et la réponse.\n\n2. À l''écran : Choisir « Accord reçu », la date, « Noter la mutuelle ».\nÀ dire : Un accord reçu sans rendez-vous remonte chaque matin. Le rendez-vous se prend dans le logiciel du cabinet.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tiroma-mutuelle');
insert into omega_lignes (tableau, ordre, donnees)
