select 'formation', 1073, '{"Identifiant":"tiroma-avant","Module":"TIROMA","Vidéo":"Préparer les rendez-vous","Statut":"À tourner","Ce qu''on y apprend":"Vérifier ce qui doit être prêt avant un rendez-vous.","Script":"Départ : https://omegaai.fr/espace2/tiroma/avant\n\n1. À l''écran : Avant les rendez-vous, onglets Laboratoire, Implants, Devis et mutuelle.\nÀ dire : Avant chaque rendez-vous, TIROMA liste ce qui doit être prêt : le travail du laboratoire, les implants, l''accord de la mutuelle.\n\n2. À l''écran : « Copier la relance du laboratoire ».\nÀ dire : Copiez la relance du laboratoire ou la commande d''implants, et envoyez-la vous-même.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tiroma-avant');
