select 'formation', 1075, '{"Identifiant":"tamila-ouvrir","Module":"TAMILA","Vidéo":"Ouvrir un dossier","Statut":"À tourner","Ce qu''on y apprend":"Créer un dossier chiffré.","Script":"Départ : https://omegaai.fr/espace2/tamila\n\n1. À l''écran : « Nouveau dossier », remplir la référence et l''intitulé, « Ouvrir le dossier ».\nÀ dire : Une clé est tirée dans votre navigateur : la référence, l''intitulé et le numéro RG sont chiffrés avant de partir.\n\n2. À l''écran : Montrer la page du dossier et ses onglets.\nÀ dire : Le dossier s''ouvre sur ses onglets : vue d''ensemble, procédure, pièces, honoraires, conformité. Chaque lecture est tracée au journal des accès.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tamila-ouvrir');
