select 'formation', 1076, '{"Identifiant":"tamila-delais","Module":"TAMILA","Vidéo":"Poser et confirmer un délai","Statut":"À tourner","Ce qu''on y apprend":"Déclarer l''appel, faire calculer un délai, le faire confirmer par un avocat.","Script":"Départ : https://omegaai.fr/espace2/tamila\n\n1. À l''écran : Dans le dossier, « + », « Déclarer l''appel… », « Enregistrer ».\nÀ dire : Déclarez l''appel : ses délais commencent à courir.\n\n2. À l''écran : « + », « Délai de procédure… », « Calculer la date », « Enregistrer ».\nÀ dire : TAMILA calcule l''échéance avec la règle, le départ, la cour et le domicile du client.\n\n3. À l''écran : « Confirmer le délai », « Approuver ».\nÀ dire : Un avocat qui voit le dossier confirme chaque délai.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'tamila-delais');
