insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1081, '{"Identifiant":"tamila-cloture","Module":"TAMILA","Vidéo":"Clôturer un dossier","Statut":"À tourner","Ce qu''on y apprend":"Exporter puis demander la clôture d''un dossier.","Script":"Départ : https://omegaai.fr/espace2/tamila\n\n1. À l''écran : Menu « … », « Exporter le dossier… », « Demander l''export ».\nÀ dire : Avant de clôturer, exportez le dossier. L''export est une lecture tracée.\n\n2. À l''écran : « Clôturer le dossier… », « Demander la clôture ».\nÀ dire : Un associé décide. Une fois clos, le dossier est effacé quelques jours plus tard, sept par défaut : pièces, parties, clé. Vous gardez l''export.","Durée":"","Lien":""}'::jsonb
