select 'formation', 1083, '{"Identifiant":"varelo-referentiel","Module":"VARELO","Vidéo":"Rapprocher le référentiel","Statut":"À tourner","Ce qu''on y apprend":"Lancer un passage de rapprochement et corriger le référentiel.","Script":"Départ : https://omegaai.fr/espace2/varelo/referentiel\n\n1. À l''écran : Référentiel, « Lancer un passage », « Lancer maintenant ».\nÀ dire : VARELO rapproche les clients, fournisseurs et articles de toutes les sociétés, et propose des lots à valider.\n\n2. À l''écran : Sur une paire douteuse d''un lot, « Écarter », « Écarter ».\nÀ dire : Une paire fausse s''écarte : le code repart seul et ne sera pas reproposé.\n\n3. À l''écran : Ouvrir un objet, « Fusionner dans… », « Proposer ».\nÀ dire : Une correction est proposée ; elle attend la décision du référent données. Celui qui la propose ne la décide pas.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'varelo-referentiel');
