where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'varelo-contrats');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1085, '{"Identifiant":"varelo-reserves","Module":"VARELO","Vidéo":"Émettre une réserve transporteur","Statut":"À tourner","Ce qu''on y apprend":"Enregistrer une livraison abîmée et émettre la réserve.","Script":"Départ : https://omegaai.fr/espace2/varelo/operations\n\n1. À l''écran : Opérations, « Nouveau », « Enregistrer une livraison », « Enregistrer la livraison ».\nÀ dire : Une livraison abîmée ou incomplète s''enregistre. « Sous réserve de déballage » sur le bon ne vaut pas réserve.\n\n2. À l''écran : Sur la carte, « Lettre de protestation », « Copier le texte ».\nÀ dire : VARELO prépare la lettre de protestation, à envoyer en recommandé avant la date indiquée. C''est vous qui l''envoyez.","Durée":"","Lien":""}'::jsonb
