select 'formation', 1089, '{"Identifiant":"espace-accueil","Module":"Votre espace au quotidien","Vidéo":"La vue d''ensemble","Statut":"À tourner","Ce qu''on y apprend":"Lire la page d''accueil de l''espace.","Script":"Départ : https://omegaai.fr/espace2\n\n1. À l''écran : Ouvrir la vue d''ensemble.\nÀ dire : La vue d''ensemble montre la courbe des factures reçues, ce qu''il faut payer en priorité, vos tâches du jour et l''activité récente.\n\n2. À l''écran : Menu de la courbe, « 30 derniers jours ».\nÀ dire : Changez la période de la courbe : 7, 30 ou 90 jours.\n\n3. À l''écran : « Voir tout » sous « À payer en priorité ».\nÀ dire : « Voir tout » mène à l''écran complet.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-accueil');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1090, '{"Identifiant":"espace-delegation","Module":"Votre espace au quotidien","Vidéo":"Déléguer pendant une absence","Statut":"À tourner","Ce qu''on y apprend":"Faire décider quelqu''un à votre place pendant une absence, puis révoquer.","Script":"Départ : https://omegaai.fr/espace2/validations\n\n1. À l''écran : Ouvrir une demande dans À valider, « Déléguer ».\nÀ dire : Vous partez en congés ? Déléguez votre décision.\n\n2. À l''écran : Choisir « À qui », la portée, la date « Jusqu''au », le motif, puis « Poser la délégation ».\nÀ dire : La personne désignée décidera en votre nom, sur ce module ou sur tous, jusqu''à la date choisie.\n\n3. À l''écran : Carte « Délégations », « Gérer », « Révoquer ».\nÀ dire : Vous pouvez révoquer à tout moment. Les décisions déjà prises restent valables.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-delegation');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1091, '{"Identifiant":"espace-equipe","Module":"Votre espace au quotidien","Vidéo":"Gérer l''équipe","Statut":"À tourner","Ce qu''on y apprend":"Ajouter une personne, changer son rôle, limiter ses sociétés, la retirer.","Script":"Départ : https://omegaai.fr/espace2/equipe\n\n1. À l''écran : Équipe, « Inviter », saisir l''adresse de son compte, choisir le rôle, « Ajouter ».\nÀ dire : La personne doit déjà avoir un compte Omega : l''invitation par courriel arrive bientôt. Sinon, écrivez-nous.\n\n2. À l''écran : Menu « ··· » d''une personne, « Rôle ».\nÀ dire : Changez son rôle : il fixe ce qu''elle voit et ce qu''elle décide.\n\n3. À l''écran : « Sociétés visibles… », cocher, « Enregistrer ».\nÀ dire : Limitez-la à certaines sociétés : elle ne voit et ne décide que pour celles-ci.\n\n4. À l''écran : « Retirer de l''organisation… », « Retirer ».\nÀ dire : Une personne retirée perd l''accès. Ce qu''elle a fait reste au journal, à son nom.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-equipe');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1092, '{"Identifiant":"espace-activite","Module":"Votre espace au quotidien","Vidéo":"Activité et automatisations","Statut":"À tourner","Ce qu''on y apprend":"Retrouver ce qui s''est passé, et chaque passage d''un système.","Script":"Départ : https://omegaai.fr/espace2/activite\n\n1. À l''écran : Activité, choisir « 7 jours », filtrer « Décisions ».\nÀ dire : L''activité retrace les documents reçus, les demandes à valider et les décisions.\n\n2. À l''écran : « Voir le détail », puis « Ouvrir dans À valider ».\nÀ dire : Chaque ligne mène à son objet.\n\n3. À l''écran : Ouvrir Automatisations, onglet « Échouées ».\nÀ dire : Automatisations montre chaque passage de vos systèmes, par état : en cours, réussi, échoué.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-activite');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1093, '{"Identifiant":"espace-taches","Module":"Votre espace au quotidien","Vidéo":"Les tâches","Statut":"À tourner","Ce qu''on y apprend":"Noter ce qu''il reste à faire, avec une échéance.","Script":"Départ : https://omegaai.fr/espace2/taches\n\n1. À l''écran : Tâches, « Nouvelle tâche », titre, priorité, échéance, « Créer la tâche ».\nÀ dire : Notez ce qu''il reste à faire, avec une priorité et une échéance.\n\n2. À l''écran : Cocher une tâche faite.\nÀ dire : Cochez-la quand elle est faite.\n\n3. À l''écran : Pointer la mention de l''appareil.\nÀ dire : Pour l''instant, vos tâches sont gardées sur cet appareil : vos collègues ne les voient pas encore.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-taches');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1094, '{"Identifiant":"espace-carnet","Module":"Votre espace au quotidien","Vidéo":"Contacts, notes et appels","Statut":"À tourner","Ce qu''on y apprend":"Tenir vos contacts, vos notes et le suivi de vos appels.","Script":"Départ : https://omegaai.fr/espace2/appels\n\n1. À l''écran : Appels, « Nouvel appel », avec qui, ce qui a été dit, Enregistrer.\nÀ dire : Notez un appel et ce qui s''est dit.\n\n2. À l''écran : « Suivi », choisir une date.\nÀ dire : Prévoyez un suivi : passé la date, l''appel s''affiche en retard.\n\n3. À l''écran : Ouvrir Contacts, « Nouveau contact ».\nÀ dire : Contacts, entreprises et notes fonctionnent de la même façon. Pour l''instant, tout est enregistré sur cet appareil.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-carnet');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1095, '{"Identifiant":"espace-utilisation","Module":"Votre espace au quotidien","Vidéo":"Utilisation et carte","Statut":"À tourner","Ce qu''on y apprend":"Mesurer ce que l''espace a traité, et voir le circuit de vos systèmes.","Script":"Départ : https://omegaai.fr/espace2/utilisation\n\n1. À l''écran : Utilisation, menu « Période ».\nÀ dire : Utilisation montre ce que l''espace a traité sur la période : documents, demandes, montants facturés et payés.\n\n2. À l''écran : Ouvrir Carte.\nÀ dire : La carte montre vos systèmes en circuit : ce qui arrive, ce qu''ils en font, ce qui vous attend, où le travail aboutit.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-utilisation');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1096, '{"Identifiant":"espace-reglages","Module":"Votre espace au quotidien","Vidéo":"Réglages et vos données","Statut":"À tourner","Ce qu''on y apprend":"Exporter vos données et passer de l''exemple à vos données.","Script":"Départ : https://omegaai.fr/espace2/reglages\n\n1. À l''écran : Réglages, « Afficher la base réelle ».\nÀ dire : Sans compte, l''espace montre une entreprise d''exemple. Ce réglage passe de l''exemple à vos données.\n\n2. À l''écran : Montrer « Exporter toutes mes données ».\nÀ dire : Vous exportez vos données à tout moment, dans une archive chiffrée. Le mot de passe n''est montré qu''une fois : notez-le.\n\n3. À l''écran : Montrer « Exporter mon journal (CSV) ».\nÀ dire : Le gérant et les administrateurs exportent aussi le journal.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'espace-reglages');
insert into omega_lignes (tableau, ordre, donnees)
select 'formation', 1097, '{"Identifiant":"reseau-apercu","Module":"Le Réseau Omega","Vidéo":"Aperçu du Réseau Omega","Statut":"À tourner","Ce qu''on y apprend":"Découvrir ce que sera le Réseau, sur les données d''exemple.","Script":"Départ : https://omegaai.fr/espace2/reseau\n\n1. À l''écran : Ouvrir Réseau, montrer « Le réseau ouvre bientôt », puis « Voir les données d''exemple ».\nÀ dire : Le Réseau Omega met les clients d''Omega en relation. Il ouvre bientôt ; en attendant, les données d''exemple montrent à quoi il ressemblera.\n\n2. À l''écran : Parcourir le Fil, puis Membres, Messages et Opportunités.\nÀ dire : Le fil réunit les demandes et les alertes des membres ; l''annuaire, les membres vérifiés ; les messages, les échanges privés et les salons ; les opportunités, les mises en relation et les achats groupés.\n\n3. À l''écran : Rester sur l''écran.\nÀ dire : Ce que vous voyez ici est un aperçu : rien n''est encore envoyé ni partagé. Rien ne le sera sans votre accord.","Durée":"","Lien":""}'::jsonb
where not exists (select 1 from omega_lignes where tableau = 'formation' and donnees->>'Identifiant' = 'reseau-apercu');
commit;
